-- 促销两类管理页面。可重复执行，不授予角色，不删除或覆盖已有菜单。
BEGIN;
SET @mall_root=(SELECT menu_id FROM sys_menu WHERE parent_id=0 AND path='mall' AND menu_type='M' ORDER BY menu_id LIMIT 1);
SET @promotion_root=(SELECT menu_id FROM sys_menu WHERE parent_id=@mall_root AND path='promotion' AND menu_type='M' ORDER BY menu_id LIMIT 1);
SET @activity_page=(SELECT menu_id FROM sys_menu WHERE parent_id=@promotion_root AND path='reward-activity' AND menu_type='C' ORDER BY menu_id LIMIT 1);
SET @activity_page=(SELECT menu_id FROM sys_menu WHERE parent_id=@promotion_root AND path='discount-activity' AND menu_type='C' ORDER BY menu_id LIMIT 1);
COMMIT;
